    c0=min(c for r in rows for c in range(tw) if mask[r,c]); c1=max(c for r in rows for c in range(tw) if mask[r,c])
    T=mask[np.ix_(rows, range(c0,c1+1))]
    print(key,'T shape',T.shape)
    want={}
    for r in range(th):
        for c in range(tw):
            want[(r,c)] = 2 if O[r,c]==8 else (1 if O[r,c]==2 else 0)
    cands=[]
    for dr in range(-th,th):
        for dc in range(-tw,tw):
            if dr==0 and dc==0: continue
            # candidate must fit some cell inside grid
            cells=[(r,c) for r in range(th) for c in range(tw) if 0<=r-dr<th and 0<=c-dc<tw and T[r-dr,c-dc]==2]
            if cells: cands.append((dr,dc,cells))
    best=None
    for attempt in range(20):
        rng=random.Random(attempt)
        picks=[]; uncovered=set(want)
        while uncovered:
            best_pick=None
            for i,(dr,dc,cells) in enumerate(cands):
                bad=sum(1 for (r,c) in cells if (r,c) not in uncovered or want[(r,c)]==0)
                if bad==0:
                    hit=sum(1 for (r,c) in cells if (r,c) in uncovered)
                    if best_pick is None or hit>best_pick[1]: best_pick=(i,hit)
            if best_pick is None: break
            picks.append(cands[best_pick[0]][2]); uncovered-=set(picks[-1])
        covm=np.zeros((th,tw),int)
        for cells in picks:
            for (r,c) in cells: covm[r,c]+=1
        err=sum(1 for (r,c) in want if covm[r,c]!=want[(r,c)])
        if best is None or err<best[0]: best=(err,len(picks),picks)
    print(key,'best greedy: err=%d picks=%d'%(best[0],best[1]))

