def get_tile_and_sep(A):
    H,W=A.shape
    vals,cnt=np.unique(A,return_counts=True)
    sep=[v for v,c in zip(vals,cnt) if c>H or c>W]  # full-line color
    mask=(A==2)
    comp=[]
    seen=np.zeros_like(mask)
    st=[(0,0)] if mask[0,0] else [(next((i,j) for i in range(H) for j in range(W) if mask[i,j]),)]
    while st:
        r,c=st.pop()
        if seen[r,c]: continue
        seen[r,c]=True; comp.append((r,c))
        for rr,cc in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
            if 0<=rr<H and 0<=cc<W and mask[rr,cc] and not seen[rr,cc]: st.append((rr,cc))
    rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
    return np.array([[1 if (r,c) in set(comp) else 0 for c in range(min(cs),max(cs)+1)] for r in range(min(rs),max(rs)+1)]), sep

