    elif flip=='fv': Q=np.flipud(P)
    elif flip=='r180': Q=np.rot90(P,2)
    res=[]
    for dr in range(-H,H+1):
        for dc in range(-W,W+1):
            C=np.zeros((H,W),bool)
            for i in range(H):
                for j in range(W):
                    ii=i-dr;jj=j-dc
                    if 0<=ii<H and 0<=jj<W: C[i,j]=Q[ii,jj]
            inter=C&P
            err=int(((O==8)!=inter).sum())
            pred=np.zeros((H,W),int)
            pred[S]=0
            u = (P|C)&(~S)
            pred[u&C]=8
            pred[(u&~C)] = 2
            err2=int((pred!=O).sum())
            res.append((err,err2,dr,dc,nm))
    return sorted(res)[:4]
