import numpy as np
def score(k, flip='id'):
    A=np.array(G[k+' input']); O=np.array(G[k+' output'])
    H,W=A.shape; S=(A==3); P=(A==2)
    Q=P.copy()
    if flip=='fh': Q=np.fliplr(P)
    elif flip=='fv': Q=np.flipud(P)
    elif flip=='r180': Q=np.rot90(P,2)
    best=[]
    for dr in range(-H,H+1):
        for dc in range(-W,W+1):
            C=np.zeros((H,W),bool)
            for i in range(H):
                for j in range(W):
                    ii=i-dr;jj=j-dc
                    if 0<=ii<H and 0<=jj<W: C[i,j]=Q[ii,jj]
            # rule: O = 8 where P&C ; 2 where P|(C-P) ; 0 elsewhere (bar gone)
            pred=np.full((H,W),0,int)
            pred[S]=0
            for i,j in zip(*np.where(C&P)): pred[i,j]=8
            for i,j in zip(*np.where(C|P)): pred[i,j]=2
            err=int((pred!=O).sum())
            o8=((O==8)); o2=((O==2)); c8=(C&P); p8=(C&~P); p2=(P&~C)
            det=f'T8={o8.sum()},T2={o2.sum()},p8={c8.sum()},p2={p2.sum()}',dr,dc
            best.append((err,det,flip,dr,dc))
    return sorted(best)[:6]
